import React from "react";
import { Link } from "react-router-dom";
import { Box, Typography, Button } from "@mui/material";
import pupImg from "../img/pup.jpg";

const HomePage = () => {
  return (
    <Box
      sx={{
        width: "100vw",
        height: "100vh",
        backgroundImage: `url(${pupImg})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Overlay */}
      <Box
        sx={{
          position: "absolute",
          width: "100%",
          height: "100%",
          backgroundColor: "rgba(0, 0, 0, 0.5)",
          zIndex: 1,
        }}
      />

      {/* Content */}
      <Box
        sx={{
          zIndex: 2,
          textAlign: "center",
          color: "white",
          padding: "32px",
          backgroundColor: "rgba(255, 255, 255, 0.1)",
          backdropFilter: "blur(6px)",
          borderRadius: "16px",
          boxShadow: 4,
        }}
      >
        <Typography
          variant="h2"
          fontWeight="bold"
          sx={{ color: "#FFD700", mb: 2 }}
        >
          PUP-OUS Exam Generator
        </Typography>

        <Typography variant="body1" fontSize="1.2rem" mb={4}>
          Empowering online examinations for students and professors alike.
        </Typography>

        <Box sx={{ display: "flex", justifyContent: "center", gap: 3 }}>
          <Link to="/signin">
            <Button
              sx={{
                backgroundColor: "#8E2839",
                color: "white",
                padding: "12px 32px",
                borderRadius: "999px",
                fontWeight: "bold",
                fontSize: "1rem",
                transition: "0.3s",
                "&:hover": {
                  backgroundColor: "#7A2231",
                },
              }}
            >
              Login
            </Button>
          </Link>
          <Link to="/signup">
            <Button
              variant="outlined"
              sx={{
                borderColor: "white",
                color: "white",
                padding: "12px 32px",
                borderRadius: "999px",
                fontWeight: "bold",
                fontSize: "1rem",
                transition: "0.3s",
                "&:hover": {
                  backgroundColor: "white",
                  color: "#8E2839",
                },
              }}
            >
              Sign Up
            </Button>
          </Link>
        </Box>
      </Box>
    </Box>
  );
};

export default HomePage;
